enum LifeEventCategory { careerBusiness('CAREER_BUSINESS'), property('PROPERTY'), vehicle('VEHICLE'), relationshipsFamily('RELATIONSHIPS_FAMILY'); const LifeEventCategory(this.wire); final String wire; }
enum LifeEventType { jobJoined('JOB_JOINED'), jobChanged('JOB_CHANGED'), promotion('PROMOTION'), roleChanged('ROLE_CHANGED'), salaryChanged('SALARY_CHANGED'), jobLoss('JOB_LOSS'), businessStarted('BUSINESS_STARTED'), careerBreakthrough('CAREER_BREAKTHROUGH'), careerSetback('CAREER_SETBACK'), other('OTHER'), propertyPurchase('PROPERTY_PURCHASE'), propertySale('PROPERTY_SALE'), vehiclePurchase('VEHICLE_PURCHASE'), vehicleSale('VEHICLE_SALE'), marriage('MARRIAGE'), engagement('ENGAGEMENT'), childBirth('CHILD_BIRTH'); const LifeEventType(this.wire); final String wire; }
enum LifeEventPrecision { day('DAY'), month('MONTH'), year('YEAR'); const LifeEventPrecision(this.wire); final String wire; }
class LifeEventDate { const LifeEventDate({required this.precision,required this.year,this.month,this.day}); final LifeEventPrecision precision; final int year; final int? month; final int? day; Map<String,Object> toJson()=>{'precision':precision.wire,'year':year,'month':?month,'day':?day}; factory LifeEventDate.fromJson(Map<String,dynamic> v)=>LifeEventDate(precision:LifeEventPrecision.values.firstWhere((x)=>x.wire==v['precision']),year:v['year'] as int,month:v['month'] as int?,day:v['day'] as int?); }
class LifeEvent { const LifeEvent({required this.id,required this.birthProfileId,required this.category,required this.type,required this.date,this.title,this.note}); final String id,birthProfileId; final LifeEventCategory category; final LifeEventType type; final LifeEventDate date; final String? title,note; factory LifeEvent.fromJson(Map<String,dynamic> v)=>LifeEvent(id:v['lifeEventId'] as String,birthProfileId:v['birthProfileId'] as String,category:LifeEventCategory.values.firstWhere((x)=>x.wire==v['category']),type:LifeEventType.values.firstWhere((x)=>x.wire==v['eventType']),date:LifeEventDate.fromJson(Map<String,dynamic>.from(v['eventDate'] as Map)),title:v['title'] as String?,note:v['note'] as String?); }
class LifeEventInput { const LifeEventInput({required this.category,required this.type,required this.date,this.title,this.note}); final LifeEventCategory category; final LifeEventType type; final LifeEventDate date; final String? title,note; Map<String,Object?> toJson()=>{'category':category.wire,'eventType':type.wire,'eventDate':date.toJson(),'title':title,'note':note}; }
const lifeEventTypes = <LifeEventCategory,List<LifeEventType>>{LifeEventCategory.careerBusiness:[LifeEventType.jobJoined,LifeEventType.jobChanged,LifeEventType.promotion,LifeEventType.roleChanged,LifeEventType.salaryChanged,LifeEventType.jobLoss,LifeEventType.businessStarted,LifeEventType.careerBreakthrough,LifeEventType.careerSetback,LifeEventType.other],LifeEventCategory.property:[LifeEventType.propertyPurchase,LifeEventType.propertySale],LifeEventCategory.vehicle:[LifeEventType.vehiclePurchase,LifeEventType.vehicleSale],LifeEventCategory.relationshipsFamily:[LifeEventType.marriage,LifeEventType.engagement,LifeEventType.childBirth]};
